<script lang="ts">
import {themes,themeFamilies,type Settings} from '$lib/api';
let {settings,onChange}:{settings:Settings;onChange:(patch:Partial<Settings>)=>Promise<void>}=$props();
let family=$state('all');let onlyFavorites=$state(false);let intensity=$state(.45);
$effect(()=>{intensity=settings.theme_intensity??.45});
const visible=$derived(themes.filter(t=>(family==='all'||t.family===family)&&(!onlyFavorites||settings.theme_favorites?.includes(t.id))));
async function favorite(id:string){const list=settings.theme_favorites||[];await onChange({theme_favorites:list.includes(id)?list.filter(x=>x!==id):[...list,id]})}
</script>
<div class="material-controls">
<div class="family-row" aria-label="Familles de thèmes"><button class:active={family==='all'} onclick={()=>family='all'} aria-pressed={family==='all'}>Tous · 44</button>{#each themeFamilies as item}<button class:active={family===item.id} onclick={()=>family=item.id} aria-pressed={family===item.id}>{item.name}</button>{/each}</div>
<label class="favorite-filter"><input type="checkbox" bind:checked={onlyFavorites}/>Mes favoris</label>
<label class="intensity" for="material-intensity">Matière <strong>{Math.round(intensity*100)} %</strong><input id="material-intensity" aria-label="Intensité de la matière" type="range" min="0" max="1" step=".05" bind:value={intensity} onchange={()=>onChange({theme_intensity:Number(intensity)})}/></label>
<p class="hint">Les 36 matières et les 8 thèmes classiques sont embarqués. Le choix et les favoris sont retrouvés au prochain démarrage.</p>
</div>
<div class="material-grid">{#each visible as item}<article class:chosen={settings.theme===item.id}><button class="choose" onclick={()=>onChange({theme:item.id})} aria-pressed={settings.theme===item.id}><span class="palette" style:background={item.background}></span><strong>{item.name}</strong><span class="selected-label">{settings.theme===item.id?'✓ Sélectionné':themeFamilies.find(x=>x.id===item.family)?.name}</span></button><button class="favorite" onclick={()=>favorite(item.id)} aria-label={`${settings.theme_favorites?.includes(item.id)?'Retirer':'Ajouter'} ${item.name} ${settings.theme_favorites?.includes(item.id)?'des':'aux'} favoris`} aria-pressed={settings.theme_favorites?.includes(item.id)||false}>{settings.theme_favorites?.includes(item.id)?'★':'☆'}</button></article>{/each}</div>
{#if visible.length===0}<p class="hint">Aucun favori dans cette famille. L’étoile permet de garder les thèmes que tu préfères.</p>{/if}
<style>
.material-controls{margin:20px 0}.family-row{display:flex;flex-wrap:wrap;gap:6px}.family-row button{min-height:44px;padding:8px 12px;border:1px solid var(--border);border-radius:8px;background:var(--surface);font-size:12px}.family-row .active{background:var(--accent);color:var(--on-accent);border-color:var(--accent)}.favorite-filter{display:flex;gap:8px;align-items:center;min-height:44px;font-size:13px;margin-top:8px}.favorite-filter input{accent-color:var(--accent);width:18px;height:18px}.intensity{display:grid;grid-template-columns:1fr auto;gap:10px;font-size:13px;max-width:360px;margin:14px 0}.intensity input{grid-column:1/-1;width:100%;accent-color:var(--accent);height:30px}.hint{color:var(--muted);font-size:12px;line-height:1.6}.material-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:24px}.material-grid article{position:relative;border:1px solid var(--border);border-radius:10px;background:var(--surface);min-width:0;overflow:hidden}.material-grid article.chosen{border-color:var(--accent);outline:1px solid var(--accent)}.choose{display:flex;flex-direction:column;width:100%;padding:8px;gap:8px;background:none;border:0;text-align:left;min-height:138px}.palette{height:74px;display:block;width:100%;border-radius:5px}.choose strong{font-size:12px;padding-right:28px}.selected-label{font-size:11px;color:var(--muted)}.favorite{position:absolute;right:2px;bottom:14px;border:0;background:var(--surface);color:var(--accent);font-size:23px;width:44px;height:44px;border-radius:7px}@media(max-width:820px){.material-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
